  const out = [];
  let node = root;
  while (node !== null) {
    if (node.left === null) {
      out.push(node.val);                 // nothing smaller left: visit, go right
      node = node.right;
      continue;
    }
    let pred = node.left;                 // the rightmost node of the left subtree
    while (pred.right !== null && pred.right !== node) pred = pred.right;
    if (pred.right === null) {
      pred.right = node;                  // thread back to here, then do the left side
      node = node.left;
    } else {
      pred.right = null;                  // the left side is done: remove the thread,
      out.push(node.val);                 // visit this node, go right
      node = node.right;
    }
  }
  return out;
}

